L000416	\section{It\^o representation of the inertial-range dynamics}
L000417	
L000418	Dynamics in the inertial interval is governed by the Stratonovich SDE system
L000419	\begin{equation}\label{eq:strat-theta-appSM}
L000420	d\theta_n
L000421	=
L000422	\Bigl(
L000423	\gamma^{2n-2}\theta_{n-1}
L000424	-\gamma^{2n}\theta_{n+1}
L000425	\Bigr)\,dt
L000426	+\varepsilon
L000427	\Bigl(
L000428	\gamma^{n-1}\theta_{n-1}\circ dw_{n-1}
L000429	-\gamma^n \theta_{n+1}\circ dw_n
L000430	\Bigr),
L000431	\end{equation}
L000432	where $\gamma=\lambda^{1/3}$ and $w_n(t)$ are independent Wiener processes.
L000433	The It\^o formulation of Eq.~(\ref{eq:strat-theta-appSM}) reads
L000434	\begin{equation}\label{eq:ito-theta-app}
L000435	d\theta_n
L000436	=
L000437	\Big[
L000438	\gamma^{2n-2}\theta_{n-1}
L000439	-\gamma^{2n}\theta_{n+1}
L000440	-\frac{\varepsilon^2}{2}\bigl(\gamma^{2n-2}+\gamma^{2n}\bigr)\theta_n
L000441	\Big]dt
L000442	+\varepsilon
L000443	\bigl(
L000444	\gamma^{n-1}\theta_{n-1}\,dw_{n-1}
L000445	-\gamma^n\theta_{n+1}\,dw_n
L000446	\bigr).
L000447	\end{equation}
L000448	Applying It\^o's formula, we obtain the closed It\^o system for the multipliers $x_n = \theta_n/\theta_{n-1}$ as
L000449	\begin{equation}\label{eq:xn-full-app}
L000450	\begin{aligned}
L000451	dx_n
L000452	={}&
L000453	\biggl[
L000454	\gamma^{2n-2}(1+x_n^2)
L000455	-\gamma^{2n}x_n x_{n+1}
L000456	-\gamma^{2n-4}\frac{x_n}{x_{n-1}}
L000457	\biggr]dt
L000458	+\varepsilon^2 x_n
L000459	\biggl[
L000460	\gamma^{2n-4}\Bigl(\frac12+\frac{1}{x_{n-1}^2}\Bigr)
L000461	+\gamma^{2n-2}(1+x_n^2)
L000462	-\frac{\gamma^{2n}}{2}
L000463	\biggr]dt
L000464	\\
L000465	&\quad
L000466	+\varepsilon
L000467	\biggl[
L000468	-\gamma^{n-2}\frac{x_n}{x_{n-1}}\,dw_{n-2}
L000469	+\gamma^{n-1}(1+x_n^2)\,dw_{n-1}
L000470	-\gamma^n x_n x_{n+1}\,dw_n
L000471	\biggr].
L000472	\end{aligned}
L000473	\end{equation}
L000474	The drift term contains contributions inherited from the deterministic dynamics as well as the It\^o correction, while the noise is local in scale and involves three neighboring Wiener processes \(dw_{n-2},dw_{n-1},dw_n\).
L000475	Representing $x_n=\gamma^{-1}+\varepsilon z_n$, we obtain the transformed SDE system
L000476	\begin{equation}
L000477	dz_n = a_n(z,\varepsilon)\,dt+\sum_{m} B_{nm}(z,\varepsilon)\,dw_m,
L000478	\label{eq_SDE_zSM}
L000479	\end{equation}
L000480	with the drift
L000481	\begin{equation}
L000482	\begin{aligned}
L000483	a_n(z,\varepsilon)
L000484	={}&
L000485	\gamma^{2n-3}
L000486	\Bigg[
L000487	2z_n-\gamma^2(z_n+z_{n+1})
L000488	-\frac{z_n-z_{n-1}}{1+\varepsilon\gamma z_{n-1}}
L000489	+\varepsilon\gamma\bigl(z_n^2-\gamma^2 z_n z_{n+1}\bigr)
L000490	\Bigg]
L000491	\\
L000492	&\quad
L000493	+\varepsilon\,\gamma^{2n-5}(1+\varepsilon\gamma z_n)
L000494	\Bigg[
L000495	\frac12+\frac{\gamma^2}{(1+\varepsilon\gamma z_{n-1})^2}
L000496	+\gamma^2+(1+\varepsilon\gamma z_n)^2-\frac{\gamma^4}{2}
L000497	\Bigg]
L000498	\end{aligned}
L000499	\label{eq:drift_an}
L000500	\end{equation}
L000501	and noise coefficients
L000502	\begin{equation}
L000503	\begin{aligned}
L000504	B_{nm}(z,\varepsilon)
L000505	=
L000506	-\gamma^{n-2}\frac{1+\varepsilon\gamma z_n}{1+\varepsilon\gamma z_{n-1}}\,\delta_{m,n-2}
L000507	+\gamma^{n-3}\Bigl[\gamma^2+(1+\varepsilon\gamma z_n)^2\Bigr]\delta_{m,n-1}
L000508	-\gamma^{n-2}(1+\varepsilon\gamma z_n)(1+\varepsilon\gamma z_{n+1})\,\delta_{m,n}.
L000509	\end{aligned}
L000510	\label{eq:diffusion_Bnm}
L000511	\end{equation}
L000512	
L000513	System \eqref{eq_SDE_zSM} possesses a hidden scaling symmetry:
L000514	\begin{equation}
L000515	z_n(t) \mapsto z_{n+s}(\gamma^{-2s}t),
L000516	\quad
L000517	w_n(t) \mapsto \gamma^s\,w_{n+s}(\gamma^{-2s}t),
L000518	\quad
L000519	s \in \mathbb{Z}.
L000520	
L000521	
L000522	
L000523	\label{eq_HSSM}
L000524	\end{equation}
L000525	The assumption that the hidden scaling symmetry is restored statistically plays a central role in the perturbative construction developed below. In particular, it implies that the stationary statistics in the inertial interval are invariant under shell translations, which leads naturally to the Toeplitz structure of the covariance matrix and to the translation-invariant structure of higher-order correction tensors. In this sense, the inertial-range dynamics can be viewed as a statistically homogeneous system in logarithmic scale space.
L000526	
L000527	The drift vector \(a(z,\varepsilon)\) and the noise matrix \(B(z,\varepsilon)\) admit the expansions
L000528	\begin{align}
L000529	a(z,\varepsilon) &= A^{(0)} z+\varepsilon a^{(1)}(z)+\varepsilon^2 a^{(2)}(z)+\cdots,
L000530	\label{eq_a_exp} \\
L000531	B(z,\varepsilon) &= B^{(0)}+\varepsilon B^{(1)}(z)+\varepsilon^2 B^{(2)}(z)+\cdots,
L000532	\label{eq_B_exp}
L000533	\end{align}
L000534	where \(A^{(0)}\) and \(B^{(0)}\) are constant matrices. The zeroth- and first-order terms are given by
L000535	\begin{align}
L000536	a_n^{(0)}(z)
L000537	&= (A^{(0)} z)_n
L000538	= \gamma^{2n-3}\Bigl(
L000539	z_{n-1}+(1-\gamma^2)z_n-\gamma^2 z_{n+1}
L000540	\Bigr),
L000541	\label{eq_terms_a0}
L000542	\\[2pt]
L000543	a_n^{(1)}(z)
L000544	&=
L000545	\gamma^{2n-2}\Bigl(
L000546	z_n^2+z_n z_{n-1}-z_{n-1}^2-\gamma^2 z_n z_{n+1}
L000547	\Bigr)
L000548	+\frac12\,\gamma^{2n-5}\bigl(3+4\gamma^2-\gamma^4\bigr),
L000549	\label{eq_terms_a1}
L000550	\\[2pt]
L000551	B_{nm}^{(0)}
L000552	&=
L000553	-\gamma^{n-2}\,\delta_{m,n-2}
L000554	+\bigl(\gamma^{n-1}+\gamma^{n-3}\bigr)\,\delta_{m,n-1}
L000555	-\gamma^{n-2}\,\delta_{m,n},
L000556	\label{eq_terms_B0}
L000557	\\[2pt]
L000558	B_{nm}^{(1)}(z)
L000559	&=
L000560	-\gamma^{n-1}(z_n-z_{n-1})\,\delta_{m,n-2}
L000561	+2\gamma^{n-2}z_n\,\delta_{m,n-1}
L000562	-\gamma^{n-1}(z_n+z_{n+1})\,\delta_{m,n}.
L000563	\label{eq_terms_B1}
L000564	\end{align}
L000565	We will also need the diffusion matrix
L000566	\begin{equation}
L000567	D(z,\varepsilon)= B(z,\varepsilon) B(z,\varepsilon)^T = D^{(0)}+\varepsilon D^{(1)}(z)+\varepsilon^2 D^{(2)}(z)+\cdots,
L000568	\label{eq_D_exp}
L000569	\end{equation}
L000570	whose first two terms are
L000571	\begin{equation}
L000572	D^{(0)}_{nm}
L000573	=
L000574	\gamma^{2n-6}\delta_{m,n-2}
L000575	-2(1+\gamma^2)\gamma^{2n-6}\delta_{m,n-1}
L000576	+\gamma^{2n-6}(1+4\gamma^2+\gamma^4)\delta_{m,n}
L000577	-2(1+\gamma^2)\gamma^{2n-4}\delta_{m,n+1}
L000578	+\gamma^{2n-2}\delta_{m,n+2},
L000579	\label{eq_terms_D0}
L000580	\end{equation}
L000581	\begin{align}
L000582	D^{(1)}_{nm}(z)
L000583	&=
L000584	\gamma^{2n-5}(z_{n-2}+z_n)\,\delta_{m,n-2}
L000585	-2\gamma^{2n-5}\Bigl[z_{n-1}+(2+\gamma^2)z_n\Bigr]\delta_{m,n-1}
L000586	\nonumber\\
L000587	&\quad
L000588	+\Bigl[
L000589	-2\gamma^{2n-3}z_{n-1}
L000590	+4(1+2\gamma^2)\gamma^{2n-5}z_n
L000591	+2\gamma^{2n-3}z_{n+1}
L000592	\Bigr]\delta_{m,n}
L000593	\nonumber\\
L000594	&\quad
L000595	-2\gamma^{2n-3}\Bigl[z_n+(2+\gamma^2)z_{n+1}\Bigr]\delta_{m,n+1}
L000596	+\gamma^{2n-1}(z_n+z_{n+2})\,\delta_{m,n+2}.
L000597	\label{eq_terms_D1}
L000598	\end{align}
L000599	Both matrices \(D^{(0)}\) and \(D^{(1)}(z)\) are symmetric and have bandwidth two.
L000600	
L000601	\section{Zero-order Gaussian solution}
L000602	
L000603	By setting $\varepsilon = 0$ in Eq.~(\ref{eq_SDE_zSM}), one obtains the Ornstein--Uhlenbeck (OU) process
L000604	\begin{equation}
L000605	dz_n = \sum_m A_{nm}^{(0)} z_m\,dt + \sum_m B_{nm}^{(0)}\,dw_m,
L000606	\label{eq_OUP}
L000607	\end{equation}
L000608	which has the Gaussian stationary density
L000609	\begin{equation}
L000610	\label{eq:GaussianSM}
L000611	p_0(z)=Z^{-1}\exp\!\left(-\tfrac12 z^T C^{-1} z\right).
L000612	\end{equation}
L000613	The covariance matrix $C$ is determined by the Lyapunov equation
L000614	\begin{equation}
L000615	\label{eq_for_C_infSM}
L000616	A^{(0)}C+CA^{(0)T}+D^{(0)}=0, \quad D^{(0)}=B^{(0)}B^{(0)T}.
L000617	\end{equation}
L000618	
L000619	The assumption of statistically restored hidden symmetry (\ref{eq_HSSM}) implies that the stationary distribution (\ref{eq:GaussianSM}) is invariant under shell translations \(n \mapsto n+s\). Consequently, the covariance matrix \(C\) must be symmetric and Toeplitz,
L000620	\begin{equation}
L000621	\label{eq_C_to_c}
L000622	C_{nm} = c_{|n-m|}.
L000623	\end{equation}
L000624	We now substitute this ansatz into \eqref{eq_for_C_infSM} with the matrices (\ref{eq_terms_a0}) and (\ref{eq_terms_D0}). Evaluating the resulting equations along each diagonal \(l \ge 0\), we obtain the recurrence relations
L000625	\begin{align}
L000626	&\text{for } l=0:\qquad
L000627	2(1-\gamma^2)(c_0+c_1)+\gamma^{-3}(\gamma^4+4\gamma^2+1)=0,
L000628	\label{eq:c_l0}
L000629	\\[2mm]
L000630	&\text{for } l=1:\qquad
L000631	(1-\gamma^4)(c_1+c_2)-2(\gamma+\gamma^{-1})=0,
L000632	\label{eq:c_l1}
L000633	\\[2mm]
L000634	&\text{for } l=2:\qquad
L000635	(1-\gamma^6)c_3+(1-\gamma^2)(1+\gamma^4)c_2+(\gamma^4-\gamma^2)c_1+\gamma=0,
L000636	\label{eq:c_l2}
L000637	\\[2mm]
L000638	&\text{for } l\ge 3:\qquad
L000639	(1-\gamma^{2l+2})\,c_{l+1}
L000640	+(1-\gamma^2)(1+\gamma^{2l})\,c_l
L000641	+(\gamma^{2l}-\gamma^2)\,c_{l-1}
L000642	=0.
L000643	\label{eq:c_l3}
L000644	\end{align}
L000645	
L000646	For large \(l\) and \(\gamma>1\), the dominant terms in \eqref{eq:c_l3} after multiplication by $-\gamma^{-2l}$ yield the asymptotic relation
L000647	\begin{equation}
L000648	\gamma^2 c_{l+1}+(\gamma^2-1)c_l-c_{l-1}=0.
L000649	\end{equation}
L000650	The corresponding characteristic equation \(\gamma^2 \rho^2+(\gamma^2-1)\rho-1=0\) has roots \(\rho_1=\gamma^{-2}\) and \(\rho_2=-1\).
L000651	Hence, the general asymptotic solution is
L000652	\begin{equation}
L000653	c_l \sim a_1\gamma^{-2l}+a_2(-1)^l, \qquad l\to\infty.
L000654	\end{equation}
L000655	Imposing decay of correlations selects the branch \(c_l \propto\gamma^{-2l}\), which determines a unique admissible solution.
L000656	
L000657	Given $\gamma$, the solution can be obtained numerically by introducing a cutoff $l_{\max}$ and setting $c_l=0$ for $l>l_{\max}$. Then the linear system~(\ref{eq:c_l0})--(\ref{eq:c_l3}) with $l=0,1,\ldots,l_{\max}$ can be solved with respect to $c_0,\ldots,c_{l_{\max}}$. This procedure converges as $l_{\max}$ increases, providing a stable and efficient computation of the covariance coefficients; see Fig.~\ref{figSM1}.
L000658	
L000659	\begin{figure}[tp]
L000660	\centering
L000661	\includegraphics[width=0.5\textwidth]{figKSM1.pdf}
L000662	\caption{Covariance coefficients $c_l$ for $\gamma=2^{1/3}$. Inset: $|c_l|$ in vertical log-scale for the numerical solution with cutoff $l_{\max}=70$. The dashed line shows the asymptotics $\propto \gamma^{-2l}$.}
L000663	\label{figSM1}
L000664	\end{figure}
L000665	
L000666	It is useful to derive the expression for the sum of covariance coefficients.
L000667	Let us multiply each Eq.~(\ref{eq:c_l3}) by $\gamma^{-2l}$ and sum over $l \ge 3$. Taking into account that $c_l \propto \gamma^{-2l} \to 0$ as $l \to \infty$ yields
L000668	\begin{equation}
L000669	\sum_{j \ge 4} c_j
L000670	= -\frac{(1-\gamma^{-4})c_2
L000671	+(2-\gamma^2-\gamma^{-4})c_3}{2(1-\gamma^2)}.
L000672	\end{equation}
L000673	Adding to this expression $c_1+c_2+c_3$ and using Eqs.~(\ref{eq:c_l0})--(\ref{eq:c_l2}), we find
L000674	\begin{equation}
L000675	\sum_{l\ge 1} c_{l}
L000676	=
L000677	-\frac{c_0}{2}+\frac{\gamma^2+1}{4\gamma^3}.
L000678	\label{eq_sum_cl}
L000679	\end{equation}
L000680	
L000681	\section{Perturbation expansion of the stationary Fokker--Planck equation}
L000682	
L000683	The stationary Fokker--Planck (FP) equation for system \eqref{eq_SDE_zSM} has the form
L000684	\begin{equation}
L000685	-\sum_n \partial_n \bigl(a_n(z,\varepsilon)\,p\bigr)
L000686	+\frac12\sum_{n,m} \partial_n\partial_m\bigl(D_{nm}(z,\varepsilon)\,p\bigr) = 0.
L000687	\label{eq:FP_stationary}
L000688	\end{equation}
L000689	The drift and diffusion coefficients admit the perturbative expansions
L000690	\eqref{eq_a_exp} and \eqref{eq_D_exp}. Accordingly, we seek a stationary
L000691	solution in the form of a perturbation series
L000692	\begin{equation}
L000693	p(z,\varepsilon)=p_0(z)\bigl[1+\varepsilon r_1(z)+\varepsilon^2 r_2(z)+\cdots\bigr],
L000694	\label{eq_p_expansion}
L000695	\end{equation}
L000696	with normalization conditions
L000697	\begin{equation}
L000698	\int r_k(z)p_0(z)\,dz=0, \quad k \ge 1.
L000699	\label{eq_NC}
L000700	\end{equation}
L000701	Substituting these expansions into Eq.~\eqref{eq:FP_stationary} and collecting
L000702	powers of \(\varepsilon\), we obtain a hierarchy of equations.
L000703	
L000704	At order \(\varepsilon^0\), we recover
L000705	\begin{equation}
L000706	-\sum_n \partial_n\Bigl( \big(A^{(0)}z\big)_n p_0\Bigr)
L000707	+\frac12\sum_{n,m} D^{(0)}_{nm}\,\partial_n\partial_m p_0 = 0,
L000708	\label{eq_perut_order0}
L000709	\end{equation}
L000710	which represents the FP equation for the OU process (\ref{eq_OUP}) with the Gaussian solution (\ref{eq:GaussianSM}).
L000711	
L000712	At order $\varepsilon^1$, after taking the derivatives and cancelling the common factor $p_0(z)$, one obtains
L000713	\begin{equation}
L000714	\begin{aligned}
L000715	&
L000716	-\sum_n\bigl[(A^{(0)}+D^{(0)}Q)z\bigr]_n\partial_n r_1
L000717	+\frac12\sum_{n,m}D^{(0)}_{nm}\partial_n\partial_m r_1
L000718	=
L000719	\sum_n\bigl[\partial_n a_n^{(1)}-(Qz)_n a_n^{(1)}\bigr]
L000720	\\
L000721	&
L000722	-\frac12\sum_{n,m}
L000723	\Bigl[
L000724	\partial_n\partial_m D^{(1)}_{nm}
L000725	-(Qz)_m\,\partial_n D^{(1)}_{nm}
L000726	-(Qz)_n\,\partial_m D^{(1)}_{nm}
L000727	+\bigl((Qz)_n(Qz)_m-Q_{nm}\bigr)D^{(1)}_{nm}
L000728	\Bigr], \quad Q = C^{-1}.
L000729	\end{aligned}
L000730	\label{eq:M0_operator_r}
L000731	\end{equation}
L000732	Similarly, higher orders $\varepsilon^k$, $k \ge 2$, yield a hierarchy of equations for correction terms $r_k$.
L000733	
L000734	We remark that the perturbative expansion developed here should be understood as an asymptotic expansion around a scale-invariant Gaussian fixed point associated with the hidden symmetry (\ref{eq_HSSM}). In particular, it does not capture exponentially small non-perturbative contributions, such as those associated with sign changes of multipliers. Within this picture, the non-Gaussian corrections generated by the perturbation series describe deviations from the fixed-point measure while preserving the statistically homogeneous structure of the inertial-range dynamics in logarithmic scale space.
L000735	
L000736	\subsection{Cubic terms of the first-order correction}
L000737	
L000738	Using the explicit expressions \eqref{eq_terms_a1} and \eqref{eq_terms_D1}, one
L000739	sees that the right-hand side of \eqref{eq:M0_operator_r} contains only terms
L000740	that are linear or cubic in \(z_n\). The structure of the left-hand side then
L000741	implies that the unknown function \(r_1(z)\) must also be a polynomial containing
L000742	only linear and cubic terms. The normalization condition
L000743	\eqref{eq_NC} is then satisfied automatically, since these terms are odd
L000744	with respect to \(z \mapsto -z\).
L000745	
L000746	The derivation of the cubic correction proceeds in several steps. First, we rewrite the first-order Fokker--Planck equation in terms of the dual Gaussian variables \(q=C^{-1}z\), which diagonalize Gaussian contractions. We then exploit translation and permutation symmetries to reduce the cubic coefficients to a two-index tensor \(W_{xy}\). Finally, substituting the polynomial ansatz into the perturbative equation yields a closed linear system for \(W\).
L000747	
L000748	Let \(r_1^{(c)}(z)\) denote the cubic part of the unknown function \(r_1(z)\).
L000749	Extracting the cubic terms in \eqref{eq:M0_operator_r} and using the identity
L000750	\[
L000751	A^{(0)}+D^{(0)}C^{-1}=-CA^{(0)T}C^{-1},
L000752	\]
L000753	which follows from \eqref{eq_for_C_infSM}, we obtain the equation for \(r_1^{(c)}(z)\) in the form
L000754	\begin{equation}
L000755	\sum_n \Bigl(CA^{(0)T}C^{-1}z\Bigr)_n \partial_n r_1^{(c)}
L000756	= -\sum_n (C^{-1}z)_n \alpha_n(z)
L000757	-\frac12\sum_{n,m}
L000758	(C^{-1}z)_n(C^{-1}z)_mD^{(1)}_{nm}(z),
L000759	\label{eq:r_cubic}
L000760	\end{equation}
L000761	where
L000762	\begin{equation}
L000763	\label{eq_alpha_n}
L000764	\alpha_n(z)
L000765	= \gamma^{2n-2}\bigl(
L000766	z_n^2+z_n z_{n-1}-z_{n-1}^2-\gamma^2 z_n z_{n+1}
L000767	\bigr)
L000768	\end{equation}
L000769	is the quadratic part of \(a_n^{(1)}(z)\) from Eq.~\eqref{eq_terms_a1}.
L000770	
L000771	It is convenient to solve this equation using the dual Gaussian variables
L000772	\(q=(q_n)_{n}\), defined by
L000773	\begin{equation}
L000774	\label{eq_dual_G}
L000775	z = Cq, \quad q = C^{-1}z, \quad \nabla_q = C \nabla_z,
L000776	\end{equation}
L000777	where the last identity gives the relation between derivatives.
L000778	In these variables, \eqref{eq:r_cubic} reads
L000779	\begin{equation}
L000780	\label{eq_FO_cubic_C}
L000781	\sum_n \big(A^{(0)T}q\big)_n \,\frac{\partial r_1^{(c)}}{\partial q_n}
L000782	=
L000783	-\sum_n q_n \alpha_n(Cq)
L000784	-\frac12\sum_{n,m}q_n q_m D^{(1)}_{nm}(Cq).
L000785	\end{equation}
L000786	We seek a cubic solution in the form
L000787	\begin{equation}
L000788	r_1^{(c)} = \sum_{i,j,k} w_{ijk} \,q_i q_j q_k.
L000789	\label{eq:r1_cubic_ansatz_app}
L000790	\end{equation}
L000791	Since the coefficients \(w_{ijk}\) are symmetric and translation invariant in the indices, we write
L000792	\begin{equation}
L000793	w_{ijk}=W_{xy},\quad x=j-i,\quad y=k-j.
L000794	\label{eq:W_xy_definition}
L000795	\end{equation}
L000796	Permutation symmetry implies
L000797	\begin{equation}
L000798	W_{xy}
L000799	=
L000800	W_{-x,\,x+y}
L000801	=
L000802	W_{x+y,\,-y}
L000803	=
L000804	W_{-y,\,-x}
L000805	=
L000806	W_{y,\,-x-y}
L000807	=
L000808	W_{-x-y,\,x}.
L000809	\label{eq:W_xy_symmetry}
L000810	\end{equation}
L000811	Therefore, it is sufficient to solve the problem in the fundamental sector
L000812	\begin{equation}
L000813	x\ge 0,\quad y\ge 0,
L000814	\label{eq:fund_sector_app}
L000815	\end{equation}
L000816	and recover the values outside this sector using the symmetry relations \eqref{eq:W_xy_symmetry}.
L000817	
L000818	Substituting \eqref{eq_terms_a0}, \eqref{eq_terms_D1}, \eqref{eq_C_to_c},
L000819	\eqref{eq_alpha_n}, \eqref{eq:r1_cubic_ansatz_app}, and \eqref{eq:W_xy_definition} into (\ref{eq_FO_cubic_C}),
L000820	and performing lengthy but straightforward manipulations, we obtain in the fundamental sector the system
L000821	\begin{equation}
L000822	\label{eq_W_sys}
L000823	W_{x+1,y}
L000824	+(1-\gamma^2)W_{xy}
L000825	-\gamma^2 W_{x-1,y} = \frac{F_{xy}}{3},
L000826	\qquad x \ge 0,\ y \ge 0,
L000827	\end{equation}
L000828	where
L000829	\begin{align}
L000830	F_{xy}
L000831	=\,
L000832	& \gamma c_{x+1}c_{x+y+1}
L000833	+\gamma^3 c_x c_{|x+y-1|}
L000834	-\gamma c_x c_{x+y}
L000835	-\gamma c_x c_{x+y+1}
L000836	-\frac{\gamma^2}{2}\,\delta_{x,2}\bigl(c_{y+2}+c_y\bigr)
L000837	\nonumber\\
L000838	&+\delta_{x,0}\bigl[c_{y+1}-2(1+2\gamma^2)\gamma^{-2}c_y-c_{|y-1|}\bigr]
L000839	+\delta_{x,1}\bigl[c_{y+1}+(2+\gamma^2)c_y\bigr].
L000840	\label{eq:F_sector_semiexplicit}
L000841	\end{align}
L000842	The terms with \(x=-1\) in Eq.~(\ref{eq_W_sys}) must be expressed through the symmetry relations as
L000843	\begin{equation}
L000844	\label{eq_W_sym_xneg}
L000845	W_{-1,0} = W_{0,1}, \qquad
L000846	W_{-1,y} = W_{1,y-1}, \quad y \ge 1.
L000847	\end{equation}
L000848	Relations \eqref{eq_W_sys}--\eqref{eq_W_sym_xneg} define the linear problem for
L000849	\(W_{xy}\) in the fundamental sector \eqref{eq:fund_sector_app}. Once \(W\) is found,
L000850	the cubic part of the first-order correction is reconstructed from
L000851	\eqref{eq:r1_cubic_ansatz_app}--\eqref{eq:W_xy_symmetry}.
L000852	
L000853	Given \(\gamma\) and the covariance coefficients \(c_l\), the matrix \(W\) can be computed numerically by solving the linear system \eqref{eq_W_sys}--\eqref{eq_W_sym_xneg} with cutoffs \(x\le x_{\max}\) and \(y\le y_{\max}\) imposed at sufficiently large values. The solution converges as the cutoffs increase. In the case \(\gamma=2^{1/3}\), we obtain \(W_{00}\approx 25.8962\).
L000854	We remark that it is useful to express the solution in terms of the variables
L000855	\begin{equation}
L000856	\label{eq:Z_from_W}
L000857	Z_{xy}=
L000858	\begin{cases}
L000859	W_{x-1,0}+W_{x0}, & x\ge 1,\ y = 0,\\[1mm]
L000860	W_{0y}-W_{0,y-1}, & x=0,\ y \ge 1,\\[1mm]
L000861	W_{x-1,y}+W_{xy}-W_{x-1,y-1}-W_{x,y-1}, & x\ge 1,\ y \ge 1,
L000862	\end{cases}
L000863	\end{equation}
L000864	with \(Z_{00}=W_{00}\), in which case both $F_{xy} \to 0$ and $Z_{xy} \to 0$ as $|x|+|y| \to \infty$; see Fig.~\ref{figSM2}.
L000865	
L000866	\begin{figure}[tp]
L000867	\centering
L000868	\includegraphics[width=0.7\textwidth]{figKSM2.pdf}
L000869	\caption{Color plots of (a) $\log_{10}|F_{xy}|$ and (b) $\log_{10}|Z_{xy}|$, showing the matrix elements that determine the non-Gaussian corrections. The computations are performed for $\gamma=2^{1/3}$ with cutoffs $x_{\max}=y_{\max}=35$.}
L000870	\label{figSM2}
L000871	\end{figure}
