L000873	
L000874	\subsection{Linear terms of the first-order correction}
L000875	
L000876	It is convenient to express the perturbative correction in Wick-ordered form. This representation isolates the genuinely non-Gaussian part of the perturbation by removing lower-order Gaussian contractions, while naturally separating the mean shift from the irreducible cubic correction. As a result, the perturbative structure becomes particularly transparent in terms of the dual Gaussian variables.
L000877	
L000878	To complete the first-order correction, it is convenient to combine the linear and cubic contributions in the Wick-ordered form
L000879	\begin{equation}
L000880	r_1(z) =  m \sum_n q_n+\sum_{i,j,k} w_{ijk}\, {:}\, q_i q_j q_k\,{:}\,,
L000881	\label{eq:r_allSM}
L000882	\end{equation}
L000883	where \(q=C^{-1}z\) are the dual Gaussian variables and
L000884	\begin{equation}
L000885	{:}\, q_i q_j q_k \,{:}
L000886	=
L000887	q_i q_j q_k
L000888	-\langle q_i q_j \rangle_0 q_k
L000889	-\langle q_i q_k \rangle_0 q_j
L000890	-\langle q_j q_k \rangle_0 q_i
L000891	\end{equation}
L000892	is the Wick-ordered product. Here \(\langle\cdot\rangle_0\) denotes averaging with respect to the Gaussian density \eqref{eq:GaussianSM}, in which case \(\langle q_i q_j\rangle_0 = C^{-1}_{ij}\).
L000893	By translation invariance, the linear part is characterized by a single scalar coefficient $m$. In the Wick-ordered representation, this coefficient determines the mean shift, as see below.
L000894	Using expressions (\ref{eq:GaussianSM}) and (\ref{eq:r_allSM}) in the expansion (\ref{eq_p_expansion}), we write
L000895	\begin{equation}
L000896	p(z,\varepsilon)=Z^{-1}
L000897	\exp\!\left(-\frac12 z^T C^{-1} z\right)
L000898	\Bigl[1+\varepsilon m \sum_n q_n+\varepsilon \sum_{i,j,k} w_{ijk}\, {:}\, q_i q_j q_k \,{:} +O(\varepsilon^2)\Bigr].
L000899	\label{eq:p_shifted_wick_2}
L000900	\end{equation}
L000901	Using the relation \(q=C^{-1}z\), this probability density can also be written in the form
L000902	\begin{equation}
L000903	p(z,\varepsilon)=Z^{-1}
L000904	\exp\!\left(-\frac12 \tilde z^T C^{-1} \tilde z\right)
L000905	\Bigl[1+\varepsilon \sum_{i,j,k} w_{ijk}\, {:}\, q_i q_j q_k \,{:}\, +O(\varepsilon^2)\Bigr],
L000906	\quad
L000907	\tilde z_n = z_n-\varepsilon m,
L000908	\label{eq:p_shifted_wick}
L000909	\end{equation}
L000910	where the linear term from \eqref{eq:p_shifted_wick_2} has been absorbed into the shift \(\tilde z_n=z_n-\varepsilon m\).
L000911	
L000912	We determine \(m\) from the stationarity condition for the mean. Averaging the SDE \eqref{eq_SDE_zSM} with respect to the stationary distribution \(p(z)\), we obtain
L000913	\begin{equation}
L000914	\langle a_n(z,\varepsilon)\rangle
L000915	= \int a_n(z,\varepsilon)p(z,\varepsilon)\, dz
L000916	= 0,
L000917	\label{eq_mean_order}
L000918	\end{equation}
L000919	where the mean is considered with respect to the perturbed density $p(z,\varepsilon)$ for a given $\varepsilon > 0$.
L000920	Substituting the expansions \eqref{eq_a_exp} and \eqref{eq:p_shifted_wick}, the terms of order $\varepsilon^1$ satisfy
L000921	\begin{equation}
L000922	m \sum_i \Big\langle \big(A^{(0)}z\big)_n q_i \Big\rangle_0
L000923	+ \sum_{i,j,k} w_{ijk} \Big\langle \big(A^{(0)}z\big)_n \,{:}\, q_i q_j q_k \,{:} \Big\rangle_0
L000924	+ \big\langle a_n^{(1)}(z)\big\rangle_0 = 0.
L000925	\label{eq_first_order}
L000926	\end{equation}
L000927	Since Wick ordering removes all Gaussian contractions of the cubic term with a linear variable, one has
L000928	\begin{equation}
L000929	\Big\langle \big(A^{(0)}z\big)_n \,{:}\, q_i q_j q_k \,{:} \Big\rangle_0 = 0.
L000930	\label{eq_Azqqq}
L000931	\end{equation}
L000932	Using the property $\big\langle z_k q_n \big\rangle_0 = \delta_{kn}$ of dual Gaussian variables, we find
L000933	\begin{equation}
L000934	\sum_i \Big\langle \big(A^{(0)}z\big)_n q_i \Big\rangle_0
L000935	=
L000936	\sum_{i,k} A^{(0)}_{nk}\,\langle z_k q_i\rangle_0
L000937	= \sum_k A^{(0)}_{nk} = 2(1-\gamma^2)\gamma^{2n-3},
L000938	\end{equation}
L000939	where the last equality follows from Eq.~\eqref{eq_terms_a0}.
L000940	Next, using \eqref{eq_terms_a1} with the Gaussian moments \(\langle z_n^2\rangle_0=c_0\) and
L000941	\(\langle z_n z_{n\pm1}\rangle_0=c_1\), we obtain
L000942	\begin{align}
L000943	\big\langle a_n^{(1)}(z)\big\rangle_0
L000944	&=
L000945	\gamma^{2n-2}\Bigl(
L000946	\langle z_n^2\rangle_0+\langle z_n z_{n-1}\rangle_0
L000947	-\langle z_{n-1}^2\rangle_0
L000948	-\gamma^2\langle z_n z_{n+1}\rangle_0
L000949	\Bigr)
L000950	+\frac12\gamma^{2n-5}(3+4\gamma^2-\gamma^4)
L000951	\nonumber\\
L000952	&=
L000953	\gamma^{2n-2}(1-\gamma^2)c_1
L000954	+\frac12\gamma^{2n-5}(3+4\gamma^2-\gamma^4).
L000955	\label{eq:a1_mean}
L000956	\end{align}
L000957	
L000958	Substituting Eqs.~\eqref{eq_Azqqq}--\eqref{eq:a1_mean} into \eqref{eq_first_order}, we obtain
L000959	\begin{equation}
L000960	m
L000961	=
L000962	-\frac{\gamma c_1}{2}
L000963	-\frac{3+4\gamma^2-\gamma^4}{4\gamma^2(1-\gamma^2)}
L000964	= \frac{\gamma}{2}\,c_0-\frac{\gamma^2+1}{2\gamma^2},
L000965	\label{eq:m_finalSM}
L000966	\end{equation}
L000967	where we used Eq.~(\ref{eq:c_l0}) in the last expression.
L000968	Thus, the first-order correction is naturally represented by a shifted Gaussian measure together with a Wick-ordered cubic perturbation (\ref{eq:p_shifted_wick}), and the shift is determined by Eq.~\eqref{eq:m_finalSM}.
L000969	
L000970	\section{Marginal distributions}
L000971	
L000972	The marginal distribution is defined by
L000973	\begin{equation}
L000974	p(z_n)=\int p(z)\prod_{k\ne n}dz_k,
L000975	\label{eq_p_marg}
L000976	\end{equation}
L000977	where, by a slight abuse of notation, we use the same symbol \(p\) for the full and marginal probability densities. We now compute the marginal distribution using representation \eqref{eq:p_shifted_wick_2}.
L000978	Using the centered Gaussian relations $\langle q_i z_n\rangle_0=\delta_{in}$ and $\langle z_n^2\rangle_0=c_0$,
L000979	and Wick's theorem, we find
L000980	\begin{equation}
L000981	\langle q_i | z_n\rangle_0=\frac{\delta_{in}}{c_0}\,z_n, \quad
L000982	\langle \,{:}\,q_iq_jq_k\,{:} \,| z_n\rangle_0
L000983	=
L000984	\delta_{in}\delta_{jn}\delta_{kn}
L000985	\left(
L000986	\frac{z_n^3}{c_0^3}-\frac{3z_n}{c_0^2}
L000987	\right).
L000988	\label{eq:wick_conditional_marginal}
L000989	\end{equation}
L000990	Therefore, only the diagonal coefficient \(w_{nnn}=W_{00}\) contributes, and
L000991	\begin{equation}
L000992	\sum_{i,j,k} w_{ijk}\,
L000993	\langle \,{:}\,q_iq_jq_k\,{:}\, | z_n\rangle_0
L000994	=
L000995	\frac{W_{00}}{c_0^3}
L000996	\left( z_n^3-3c_0 z_n \right).
L000997	\label{eq:rc_conditional_marginal}
L000998	\end{equation}
L000999	Substituting representation \eqref{eq:p_shifted_wick_2} into \eqref{eq_p_marg} and using expressions (\ref{eq:wick_conditional_marginal}) and (\ref{eq:rc_conditional_marginal}), we arrive at
L001000	\begin{equation}
L001001	p(z_n) =
L001002	\frac{1}{\sqrt{2\pi c_0}}
L001003	\exp\!\left(-\frac{z_n^2}{2c_0}\right)
L001004	\left[
L001005	1+\varepsilon\frac{m}{c_0}z_n+\varepsilon \frac{W_{00}}{c_0^3}
L001006	\left(z_n^3-3c_0 z_n\right) +O(\varepsilon^2)
L001007	\right].
L001008	\label{eq:marginal_shifted_final_simplifiedSM}
L001009	\end{equation}
L001010	This probability density can also be written as
L001011	\begin{equation}
L001012	p(z_n) =
L001013	\frac{1}{\sqrt{2\pi c_0}}
L001014	\exp\!\left(-\frac{(z_n-\varepsilon m)^2}{2c_0}\right)
L001015	\left[
L001016	1+\varepsilon \frac{W_{00}}{c_0^3}
L001017	\left(z_n^3-3c_0 z_n\right) +O(\varepsilon^2)
L001018	\right].
L001019	\label{eq:marginal_shifted_final_simplifiedBSM}
L001020	\end{equation}
L001021	Thus, the marginal distribution is a Gaussian with mean \(\varepsilon m\) and variance \(c_0\), multiplied by the cubic correction determined by \(W_{00}\).
L001022	
L001023	We remark that the perturbative expression (\ref{eq:marginal_shifted_final_simplifiedBSM}) is an asymptotic expansion in \(\varepsilon\). Accordingly, a finite-order truncation of the series does not necessarily define a positive probability density for sufficiently large values of \(|z_n|\). This behavior is a standard feature of asymptotic perturbative expansions and does not affect the validity of the expansion for the computation of statistical observables.
L001024	
L001025	\section{Perturbation expansion of the power-law exponents}
L001026	
L001027	In this section, we derive the perturbative corrections to the scaling exponents of the structure functions. We may assume that all multipliers \(x_n=\theta_n/\theta_{n-1}\) remain positive, which allows us to expand in \(\varepsilon\) the telescopic representation
L001028	\begin{equation}
L001029	|\theta_n|^p
L001030	= \prod_{k=1}^n x_k^p
L001031	= \prod_{k=1}^n (\gamma^{-1}+\varepsilon z_k)^p
L001032	= \gamma^{-pn} \prod_{k=1}^n (1+\varepsilon \gamma z_k)^p.
L001033	\label{eq_tele_theta}
L001034	\end{equation}
L001035	Strictly speaking, sufficiently large negative fluctuations of \(z_k\) may produce sign changes of individual multipliers \(x_k=\gamma^{-1}+\varepsilon z_k\). However, in the leading Gaussian approximation for small \(\varepsilon\), the probability of such an event scales as
L001036	\begin{equation}
L001037	\mathbb{P}(x_k<0)
L001038	=
L001039	\mathbb{P}\left(z_k<-\frac{1}{\varepsilon\gamma}\right)
L001040	\propto
L001041	\exp\left(
L001042	-\frac{1}{2c_0\gamma^2\varepsilon^2}
L001043	\right),
L001044	\end{equation}
L001045	up to subleading prefactors. These non-perturbative events are therefore beyond all algebraic orders in \(\varepsilon\) and do not affect the perturbative asymptotics of the scaling exponents.
L001046	
L001047	Expanding Eq.~(\ref{eq_tele_theta}) in powers of \(\varepsilon\) for an arbitrary exponent \(p \in \mathbb{R}\), we obtain
L001048	\begin{equation}
L001049	|\theta_n|^p
L001050	=
L001051	\gamma^{-pn}
L001052	\Bigg[
L001053	1
L001054	+p\varepsilon \gamma \sum_{k=1}^n z_k
L001055	+\frac{\varepsilon^2 \gamma^2}{2}
L001056	\left(
L001057	p^2 \Big(\sum_{k=1}^n z_k\Big)^2
L001058	- p \sum_{k=1}^n z_k^2
L001059	\right)
L001060	\Bigg]
L001061	+O(\varepsilon^3).
L001062	\label{eq_prod_tel}
L001063	\end{equation}
L001064	Taking the expectation, we write
L001065	\begin{equation}
L001066	S_p(n)
L001067	=
L001068	\gamma^{-pn}
L001069	\left[
L001070	1
L001071	+p\varepsilon \gamma \sum_{k=1}^n \langle z_k\rangle
L001072	+\frac{\varepsilon^2 \gamma^2}{2}
L001073	\left(
L001074	p^2 \left\langle \Big(\sum_{k=1}^n z_k\Big)^2 \right\rangle
L001075	- p \sum_{k=1}^n \langle z_k^2\rangle
L001076	\right)
L001077	\right]
L001078	+O(\varepsilon^3).
L001079	\label{eq:Sp_prelim}
L001080	\end{equation}
L001081	
L001082	We now compute the averages using the expansion \eqref{eq:p_shifted_wick_2}.
L001083	For the Gaussian averages $\langle \cdot \rangle_0$, we have
L001084	\begin{equation}
L001085	\langle z_k q_n\rangle_0=\delta_{kn},
L001086	\quad
L001087	\langle z_iz_j q_n\rangle_0 = 0,
L001088	\quad
L001089	\langle z_k \,{:}\, q_i q_j q_\ell \,{:}\, \rangle_0=0,
L001090	\quad
L001091	\langle z_iz_j \,{:}\, q_i q_j q_\ell \,{:}\, \rangle_0=0.
L001092	\end{equation}
L001093	Using these relations together with the expansion \eqref{eq:p_shifted_wick_2}, we obtain
L001094	\begin{equation}
L001095	\langle z_k\rangle=\varepsilon m+O(\varepsilon^2), \quad
L001096	\langle z_k z_l\rangle = c_{|k-l|}+O(\varepsilon^2).
L001097	\label{eq:zkzl_structure}
L001098	\end{equation}
L001099	Substituting \eqref{eq:zkzl_structure} into \eqref{eq:Sp_prelim}, we obtain
L001100	\begin{equation}
L001101	\begin{aligned}
L001102	S_p(n) &=
L001103	C_p\gamma^{-pn}
L001104	\Bigg[
L001105	1
L001106	+p\varepsilon^2 \gamma m\, n
L001107	+\frac{\varepsilon^2 \gamma^2}{2}
L001108	\left(
L001109	p(p-1)n c_0
L001110	+2p^2\sum_{l=1}^{n-1}(n-l)c_l
L001111	\right)+O(\varepsilon^3)
L001112	\Bigg] \\
L001113	&=
L001114	C_p\gamma^{-pn}
L001115	\exp\Bigg[
L001116	p\varepsilon^2 \gamma m\, n
L001117	+\frac{\varepsilon^2 \gamma^2}{2}
L001118	\left(
L001119	p(p-1)n c_0
L001120	+2p^2\sum_{l=1}^{n-1}(n-l)c_l
L001121	\right)+O(\varepsilon^3)
L001122	\Bigg].
L001123	\end{aligned}
L001124	\label{eq_Sp_1SM}
L001125	\end{equation}
L001126	The prefactor \(C_p\) originates from forcing-range contributions. Indeed, the distribution \eqref{eq:p_shifted_wick_2} describes only the inertial interval and is not valid in the forcing range. As a result, the multipliers associated with the first few shells (\(n\sim1\)) produce additional multiplicative contributions to the products in Eqs.~\eqref{eq_tele_theta} and \eqref{eq:Sp_prelim}. These contributions are independent of \(n\) in the large-\(n\) limit and therefore affect only the amplitudes of the structure functions.
L001127	
L001128	For large \(n\), using the exponential decay \(c_l \propto \gamma^{-2l}\) together with Eq.~(\ref{eq_sum_cl}), we obtain the asymptotic expression
L001129	\begin{equation}
L001130	\sum_{l=1}^{n-1}(n-l)c_l
L001131	\approx
L001132	n\sum_{l \ge 1}c_l
L001133	-\sum_{l \ge 1} l\,c_l
L001134	=
L001135	n\left(-\frac{c_0}{2}+\frac{\gamma^2+1}{4\gamma^3}\right)
L001136	-\sum_{l \ge 1} l\,c_l.
L001137	\label{eq_sum_cl_coef}
L001138	\end{equation}
L001139	Substituting Eqs.~(\ref{eq:m_finalSM}) and (\ref{eq_sum_cl_coef}) into Eq.~(\ref{eq_Sp_1SM}) and absorbing all \(n\)-independent contributions into the prefactor \(\tilde{C}_p\), we obtain
L001140	\begin{equation}
L001141	S_p(n) \approx
L001142	\tilde{C}_p\gamma^{-pn}
L001143	\exp\left[
L001144	\frac{\gamma^2+1}{4\gamma}p(p-2)\,\varepsilon^2 n
L001145	+O(\varepsilon^3 n)
L001146	\right].
L001147	\label{eq_Sn_exp}
L001148	\end{equation}
L001149	Using \(k_n=\lambda^n=\gamma^{3n}\), this expression can be written equivalently as the asymptotic power-law scaling
L001150	\begin{equation}
L001151	S_p(n)\propto k_n^{-\zeta_p}
L001152	=
L001153	\gamma^{-3\zeta_p n},
L001154	\qquad
L001155	\zeta_p
L001156	=
L001157	\frac{p}{3}
L001158	-\frac{\gamma^2+1}{12\gamma\ln\gamma}\,
L001159	p(p-2)\,\varepsilon^2
L001160	+O(\varepsilon^4).
L001161	\end{equation}
L001162	Remarkably, the leading anomalous correction admits an explicit expression in terms of \(\gamma=\lambda^{1/3}\). Note that the error term in the expression for \(\zeta_p\) is written as \(O(\varepsilon^4)\), since odd-order corrections vanish due to the symmetry \(\varepsilon \mapsto -\varepsilon\) in the statistics of system~(\ref{eq:strat-theta-appSM}).
L001163	
L001164	We emphasize that the perturbative expansion \eqref{eq_Sn_exp} for the structure function is understood in the asymptotic regime of small \(\varepsilon\) and large shell number \(n\), with \(\varepsilon^2 n = O(1)\). In this regime, the terms growing linearly with \(n\) determine the correction to the scaling exponents, while forcing-range contributions produce only \(n\)-independent corrections to the amplitudes of the structure functions.
L001165	
L001166	\section{Numerical simulations}
L001167	
L001168	In the numerical simulations, we take $\lambda = 2$ and $\gamma = 2^{1/3}$. We impose a cutoff at shell \(N\) by setting \(\theta_n \equiv 0\) for \(n > N\). Although the classical diffusion term \(-\kappa k_n^2 \theta_n\) vanishes in the limit \(\kappa \to 0\), it affects all scales and thus contaminates the inertial interval. To obtain a cleaner inertial range, we instead localize dissipation at the cutoff shell by introducing a dissipative term of the form \(-\gamma^{2N-1}\theta_N\).
L001169	The full system simulated is therefore
L001170	\begin{equation}
L001171	d\theta_n
L001172	=
L001173	\Bigl(
L001174	\gamma^{2n-2}\theta_{n-1}
L001175	-\gamma^{2n}\theta_{n+1}
L001176	\Bigr)\,dt
L001177	+\varepsilon
L001178	\Bigl(
L001179	\gamma^{n-1}\theta_{n-1}\circ dw_{n-1}
L001180	-\gamma^n \theta_{n+1}\circ dw_n
L001181	\Bigr)
L001182	-\delta_{nN} \gamma^{2N-1}\theta_N\,dt,
L001183	\quad
L001184	n = 1,\ldots,N,
L001185	\end{equation}
L001186	with the forcing condition \(\theta_0 = 0\).
L001187	
L001188	Time integration is performed using the Euler--Maruyama scheme for the conservative drift and stochastic parts, while the dissipative term is treated separately via a low-pass filter. The time step is chosen as $\Delta t = 0.02\,\gamma^{-2N}$.
L001189	Statistical quantities are computed over a time interval of length \(10^3\) (or longer), skipping an initial transient of length \(10^2\). The simulations exhibit period-two oscillations of statistical observables in the inertial interval. These oscillations are suppressed by averaging the statistics obtained for two consecutive cutoffs, \(N\) and \(N-1\). In the results presented here, we use \(N=23\).
L001190	
L001191	We also note that, for small $\varepsilon>0$, the distributions of the shell variables $\theta_n$ acquire a positive (albeit exponentially small) probability density at $\theta_n=0$. For the multipliers $x_n=\theta_n/\theta_{n-1}$, this implies that the covariances $\mathrm{cov}(x_n,x_{n+j})$ diverge for $j=0$ and are defined only in the principal-value sense for $j\neq 0$. This exponentially small effect is not captured by the perturbative expansion in $\varepsilon$. Nevertheless, the associated divergences become apparent in numerical computations as $\varepsilon$ increases. In Fig.~2 of the main text, we therefore use a small value $\varepsilon=0.01$ to suppress this non-perturbative contribution.
